This C#/VB.NET code shows how to acquire one image from eSCL device and cancels image transfer.

            ''' <summary>
            ''' Acquires one image from eSCL device and cancels image transfer.
            ''' </summary>
            Public Shared Sub AcquireOneImageFromEsclDeviceAndCancelScan()
                ' create eSCL device manager
                Using deviceManager As New Vintasoft.EsclImageScanning.EsclDeviceManager()
                    ' open eSCL device manager
                    deviceManager.Open()

                    ' wait while the eSCL device manager searches for eSCL devices
                    System.Threading.Thread.Sleep(deviceManager.DeviceSearchTimeout)
                    ' get count of eSCL devices
                    Dim deviceCount As Integer = deviceManager.Devices.Count
                    If deviceCount = 0 Then
                        System.Console.WriteLine("Devices are not found.")
                        Return
                    End If

                    ' select the first eSCL device
                    Dim device As Vintasoft.EsclImageScanning.EsclDevice = deviceManager.Devices(0)

                    ' open eSCL device
                    device.Open()

                    Dim acquiredImage As Vintasoft.EsclImageScanning.EsclAcquiredImage
                    Do
                        Try
                            ' acquire image from eSCL device
                            acquiredImage = device.AcquireImageSync()
                            ' if image is received
                            If acquiredImage IsNot Nothing Then
                                System.Console.WriteLine("Image is acquired.")

                                ' cancel image transfer
                                device.CancelImageTransfer()
                            Else
                                ' if image is not received
                                System.Console.WriteLine("Scan is completed.")
                                Exit Try
                            End If
                        Catch ex As System.Exception
                            System.Console.WriteLine(String.Format("Scan is failed: {0}", ex.Message))
                            Exit Try
                        End Try
                        ' while image is acquired
                    Loop While acquiredImage IsNot Nothing

                    ' close eSCL device
                    device.Close()

                    ' close eSCL device manager
                    deviceManager.Close()
                End Using

                System.Console.ReadLine()
            End Sub


            /// <summary>
            /// Acquires one image from eSCL device and cancels image transfer.
            /// </summary>
            public static void AcquireOneImageFromEsclDeviceAndCancelScan()
            {
                // create eSCL device manager
                using (Vintasoft.EsclImageScanning.EsclDeviceManager deviceManager = new Vintasoft.EsclImageScanning.EsclDeviceManager())
                {
                    // open eSCL device manager
                    deviceManager.Open();

                    // wait while the eSCL device manager searches for eSCL devices
                    System.Threading.Thread.Sleep(deviceManager.DeviceSearchTimeout);
                    // get count of eSCL devices
                    int deviceCount = deviceManager.Devices.Count;
                    if (deviceCount == 0)
                    {
                        System.Console.WriteLine("Devices are not found.");
                        return;
                    }

                    // select the first eSCL device
                    Vintasoft.EsclImageScanning.EsclDevice device = deviceManager.Devices[0];

                    // open eSCL device
                    device.Open();

                    Vintasoft.EsclImageScanning.EsclAcquiredImage acquiredImage;
                    do
                    {
                        try
                        {
                            // acquire image from eSCL device
                            acquiredImage = device.AcquireImageSync();
                            // if image is received
                            if (acquiredImage != null)
                            {
                                System.Console.WriteLine("Image is acquired.");

                                // cancel image transfer
                                device.CancelImageTransfer();
                            }
                            // if image is not received
                            else
                            {
                                System.Console.WriteLine("Scan is completed.");
                                break;
                            }
                        }
                        catch (System.Exception ex)
                        {
                            System.Console.WriteLine(string.Format("Scan is failed: {0}", ex.Message));
                            break;
                        }
                    }
                    // while image is acquired
                    while (acquiredImage != null);

                    // close eSCL device
                    device.Close();

                    // close eSCL device manager
                    deviceManager.Close();
                }

                System.Console.ReadLine();
            }

This C#/VB.NET code shows how to open eSCL device manager and display information about available eSCL image scanners.

            ''' <summary>
            ''' Opens eSCL device manager and displays information about available local eSCL image scanners.
            ''' </summary>
            Private Sub GetEsclDevicesInfo()
                ' create eSCL device manager
                Using deviceManager As New Vintasoft.EsclImageScanning.EsclDeviceManager()
                    ' open device manager
                    deviceManager.Open()

                    ' wait while the eSCL device manager searches for eSCL devices
                    System.Threading.Thread.Sleep(deviceManager.DeviceSearchTimeout)
                    ' get count of eSCL devices
                    Dim deviceCount As Integer = deviceManager.Devices.Count
                    If deviceCount = 0 Then
                        System.Console.WriteLine("Devices are not found.")
                        Return
                    End If

                    Dim devices As Vintasoft.EsclImageScanning.EsclDeviceCollection = deviceManager.Devices
                    ' for each eSCL device
                    For i As Integer = 0 To devices.Count - 1
                        ' output the device name
                        System.Console.WriteLine(String.Format("Device '{0}'", devices(i).Name))
                    Next
                End Using
            End Sub


            /// <summary>
            /// Opens eSCL device manager and displays information about available local eSCL image scanners.
            /// </summary>
            void GetEsclDevicesInfo()
            {
                // create eSCL device manager
                using (Vintasoft.EsclImageScanning.EsclDeviceManager deviceManager = new Vintasoft.EsclImageScanning.EsclDeviceManager())
                {
                    // open device manager
                    deviceManager.Open();

                    // wait while the eSCL device manager searches for eSCL devices
                    System.Threading.Thread.Sleep(deviceManager.DeviceSearchTimeout);
                    // get count of eSCL devices
                    int deviceCount = deviceManager.Devices.Count;
                    if (deviceCount == 0)
                    {
                        System.Console.WriteLine("Devices are not found.");
                        return;
                    }

                    Vintasoft.EsclImageScanning.EsclDeviceCollection devices = deviceManager.Devices;
                    // for each eSCL device
                    for (int i = 0; i < devices.Count; i++)
                    {
                        // output the device name
                        System.Console.WriteLine(string.Format("Device '{0}'", devices[i].Name));
                    }
                }
            }

